import json

with open('/home/user/workspace/13511660557912876654/buddhist-ontology/data/baihua-tasks/t2761.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

translations = data['translations']
for i, seg in enumerate(translations):
    orig = seg['original_preview']
    
    if "無盡明應身無窮智" in orig and "除眾過惡者。" in orig:
        title = "【法身常義】"
        meaning = "【義解】本段說明法身無盡、一切常住法（十力無畏等）功德，解釋法身永恆、遠離過惡的含義。"
        body = "白話：無盡光明、應身無窮、智慧無盡，是說明法身無有窮盡。一切法常住，是說十力、四無畏等功德法常住。心過惡身四種，是解釋為什麼能得常住：心無各種煩惱，身無生老病死。了知一切爾炎（爾炎是漢語「境界」的意思），攝持一切萬善法，除滅一切過惡。"
    elif "達知法總備諸善法。具此三義故得常也。" in orig and "略記五事。" in orig:
        title = "【授記五事】"
        meaning = "【義解】本段說明具三義故得法身常住，並解釋佛為勝鬘夫人授記的五個內容：自在天王因位果、無量劫修行、號普光、如來正遍知德號、國土無惡趣。"
        body = "白話：通達了知佛法總相、具備一切善法，具足這三種含義所以得常住。「我久安立汝」這一偈是佛所說。「我已作功德」以下是勝鬘所說，前面請佛護身，這裡請護法，佛就為她授記：因為她既有恭敬讚歎的功德，又禮拜請求，希望如來令她修行萬善，所以佛就為她授記。「自在王」，是授記她因中的殊勝果，將來常作自在天王；「無量阿僧祇佛」，是授記她要經過無量劫修行；「號普光」，是授記她成佛的名字；「如來正遍知」，是授記她的功德名號；「無有惡趣」，是授記她的國土與弟子的清淨。一共略記五件事。"
    elif "受十大受者。是第二經名也。" in orig and "為此二利不捨而化之。" in orig:
        title = "【十大受義】"
        meaning = "【義解】本段解釋「十大受」經名的含義：十受攝盡萬善，分為自行與化他兩類，以不染心、無厭心、無礙心攝化眾生，令佛法久住。"
        body = "白話：受十大受，是第二部經的名稱。前面是受人（記為人），後面是受法（受十大受法），人有能受的德，法有可受的理，所以以「受」為名。十種戒能攝盡萬善所以叫大，對於萬善來說是略，對於一善來說是廣。十大受大分為兩類：一是自行，二是化人，前五種受和第十受是自行，中間四種受是化他。又有兩種含義：一是別，二是總，前九是別，第十是總。「以不愛染心」，就是不捨遠疏的、不親近偏私的；「無厭足心」就是樂於常說法度人；「無礙心」就是有人請法就說；「彼彼處」就是在在處處；「應折伏者」就以威力制伏；「應攝受者」就以柔軟語教化；「令法久住」，以折伏攝受兩種方法調伏眾生，佛法得以久住，天人充滿就是善道增益。為了這兩種利益而不捨化度。"
    elif "忘失法者。則忘失大乘人法。" in orig and "可不云也。" in orig:
        title = "【失法次第】"
        meaning = "【義解】本段解釋「忘失法」就是忘失大乘，忘失大乘五義就會退失凡夫，不得聖果，過失極重。"
        body = "白話：忘失法，就是忘失大乘的人與法。總共有五義：一名正法欲，二名攝受正法，三名欲作大乘，四名波羅蜜，五名大乘造善之始。一定要先有好樂欲求的心，有了欲心就會攝受正法在自身，自己攝受後就想要行持大乘，行持大乘就知道能到達果位、知道大乘有運載的功能。勝鬘自己表明必定能具足修行成就這五義，所以說終不忘失。要說明行人失善，是從開始失最終、從最終失開始，中間次第說明失義。忘失法就是忘失大乘，這是說明失始忘終，為什麼不說「欲」呢？因為攝受的名稱在十受中，說到的時候就舉出來。不決定大乘就不能得到攝受欲，這是說明失終忘始，中間總體失壞，就是次第失善五義，就會失去世間聖人的殊勝果報，隨業流轉生死永遠做凡夫，過失非常重，就是這個意思。善是真理所以叫正法，可要求得在己所以叫攝受。"
    elif "隨所樂入者。不能反流隨受三有身曰樂。" in orig and "非義饒益者。惡果報也。" in orig:
        title = "【失法過患】"
        meaning = "【義解】本段續明忘失正法的過患：不能超越凡夫地，有無量大過；不失則得無量福利。勝鬘請佛現前作證，令大眾斷疑。"
        body = "白話：「隨所樂入」，就是不能反流逆生死，隨順三有受生叫樂。「越凡夫地」，背離聖道受生，怎麼能超越凡夫地呢。「無量大過」，失去聖人的殊勝利益，得到凡夫的卑賤所以叫大過。「無量福利」，就是種種善根聖果，修行十受就能得到；失十受，就入凡夫地，所以兩方面都說明。「現為我證」，十受名義雖多但總攝萬善，女人卑弱大家會認為不能修行，如來雖然知道其他人有疑惑，但若不是現前作證就無法斷疑。非義饒益，就是惡果報。"
    elif "雨眾天華出妙音聲者。華聲二瑞應。" in orig and "三願如空諸善如色也。" in orig:
        title = "【三願攝善】"
        meaning = "【義解】本段明天雨花、天樂瑞應，讚歎勝鬘必行十受、必成菩提，大眾發願同行，以及三大願攝盡一切善法：自行、外化、護法。"
        body = "白話：雨眾天華、出微妙音聲，是華和音聲兩種瑞應，所顯現的華表明勝鬘必能行十受，顯現的音聲表明必能成就菩提。「同其所行者」，大眾斷疑見到利益，發願同勝鬘一樣行十受。發三大願，是第三部經的名稱。前面用十種名義攝盡萬善，這裡用三種名義盡攝一切善，將要歸於一乘，所以逐漸減省名數。求善歸於自己，剛開始叫受，要期永劫就叫願。第一願是自行，第二是外化，第三是護法。「以此善根」，就是行十受的善根。「得正法智」，有智慧就知道萬善是可尊崇的。「如一切色悉入空界」，就像青黃朱紫各種顏色都被虛空包容，五戒等各種善法都被三願含攝，三願就像虛空，諸善就像顏色。"
    elif "承佛威神說調伏大願者。第四經名也。" in orig and "義顯於此矣。" in orig:
        title = "【調伏大願】"
        meaning = "【義解】本段明第四經「調伏大願」名義，說明攝受正法是一乘根本，唯有久種善根者能解，功德利益無量無邊。"
        body = "白話：承佛威神說調伏大願，是第四部經的名。一個名義攝盡萬法，需要承佛旨意才能明了。名雖然沒有兩樣，但還未顯真實義，將要闡明一乘之道，不是容易宣說的。常不輕善叫調，不生諸惡叫伏，一名攝眾叫大，永劫不捨叫願。「真實無異」，所說符合真理，又必定能實行。「所謂攝受正法者」，點出經名，更沒有別法，所以說「所謂」，有始有終，所以有「攝受」和「願」兩個名稱。「久種善根者乃能解汝所說」，含攝第一義，能了知萬善的人不是久種善根就不能悟入。「今說當說」，三世如來都說萬善，這裡說明勝鬘所說同於諸佛，為了令人相信所以多所讚美。「不得邊際」，善的理體無窮，說法哪裡能說盡。「智慧辨才亦無邊際」，這是說明如來智慧能遍知、辯才不可窮盡，不是智慧所能窮盡解了的。「有大功德有大利益」，善是功德，人得善是利益。得道時無數善法熾盛、無邊際的含義在這裡顯明。"
    elif "更復演說者。上已明體。今欲美況。" in orig and "即是攝受正法者。此明人是藏義。" in orig:
        title = "【正法大地喻】"
        meaning = "【義解】本段以大雨、大地、寶藏為比喻，說明攝受正法能出生一切善法、能載負一切眾生、能給予一切功德珍寶。"
        body = "白話：更復演說，前面已經說明本體，現在要用比喻來讚美，這是果的第二義。「得一切佛法」，是果法；「八萬四千法門」，是因法。「雨眾色雨」，這個比喻正法能出生眾善，雨有青黃等不同顏色，善有萬種差別；上面的雨是法，下面的雨是被潤澤的人。「及種種寶」，是果；「雨無量福報」，對應果；「及無量善根」，對應因。「有大水聚」，說明正法能有成熟利益的作用。「大千界藏」，比喻大乘；「四百億」，比喻二因二果；「大界藏」，對應大千世界。「神通力」，是無漏因；「如意自在」，是有漏善因；或者是果的功能不會消失。「安隱快樂」，是有漏果；「出世間安樂」，是無漏果，對應四百億的說法。「劫成訖皆於中」，創世開始一切善法都出於正法，五戒十善是別相，攝受正法是總稱，所以能出生諸願。「又如大地」，這個比喻人，受持佛法的人能載負眾生所以像大地；人天善根最終都授與大乘，這是說明持法的人，能將眾生有漏無漏的善法因果都引導向大乘。「為世法母」，能以諸善令人生人天聖果。明教師的功能到這裡。「於此又如大地有四寶藏者」，這個比喻受法的人，一切眾生如大地，四種人如同四個寶藏；前面的比喻說明人有能化的功用，這個比喻說明人有能受的意義。從「如是攝受正法」到「善男子善女人」，舉前面能化的人；「建立大地者」，舉前面能載負的人；「能得四種大寶者」，舉前面持正法的功德；「授而與之者」，授與三歸五戒乃至菩薩戒，以及宣說諸善因果，就像從寶藏中拿出七寶給人。「如是得大寶眾生者」，舉受法的人。「皆由攝受正法訖男子女人」，舉能化的人。「得此希有功德者」，總結給予和受法的人，這是說明法是寶義。「大寶藏者即是攝受正法者」，這是說明人是藏義，這裡應該有「人」字，省略了沒有說。說明受法弟子的意義到這裡。"
    elif "攝受正法攝受正法者。此是第三明法法相即。" in orig and "非真見也。" in orig:
        title = "【法相人相即】"
        meaning = "【義解】本段明法與心、人與法相即不二，攝受正法就是六度萬行，教師應觀機逗教，令眾生成熟善根。"
        body = "白話：「攝受正法攝受正法者」，這是第三層說明法與法相即：第一句是能攝受的心，第二句再重舉此法，「無異正法」是說明心不異於法，「無異攝受正法」是說明法不異於心，「正法即是攝受正法」是說明正法就是心，因為知道不二所以可以印可，也應當以心印法，不二就可以印可、可以了知。「無異波羅蜜」，是顯明正法，前面雖然玄妙地說明了，但還沒有說明本體，所以就事相更分明地解說，文字不同但義理和上面沒有差異。為什麼就六度來說明義理呢？這部經的大意，是說明菩薩行六波羅蜜是所修行的內容。「攝受正法男子女人」，這是說明教師。「應以施成熟者」，見有眾生可以教他行布施；「以施成熟者」，前面是使人受行法，布施是法，「乃至捨身枝節」，就是頭目髓腦，初修行的人從易到難，最初捨一絲一線，中間捨衣食、國城，最後捨妻子、身命，超越了初、中階段所以說「乃至」，下面五度都是這樣。「將護彼意」，能捨一絲一線的就教他捨一絲一線，乃至能捨身命的就教他捨身命，如果還不能捨身命就教他捨，他必定做不到，不能成人之美就不叫將護。「彼所成熟眾生建立正法者」，就是受行佈施的法。「是名檀波羅蜜」，說明相即的意義：能受的是心行，所行的是佈施法，二義雖異本體沒有差別，相即不二的意思很明白。一切論總共有五義：一內明論，善解佛法經論；二外明論，善解外道經書記傳論；三因明論，善解諸法因緣相待而有；四聲明論，善解各地方言語言差異；五工巧論，善解機關木人、幻術、咒術等。一切工巧就是懂機關幻術，乃至諸事，就是善於知道所作事情好壞的緣由。"
    elif "承佛威神更說大義者。第四明人法相即。" in orig and "惡何可不捨也。" in orig:
        title = "【護法之行】"
        meaning = "【義解】本段明人與法相即不二，行善的人本身就是正法；又說明護法的行為：化解諍訟、不諂曲、不欺誑、不虛偽，入正法同朋，必受佛記。"
        body = "白話：承佛威神更說大義，是第四層說明人與法相即。人與法本體應不同，現在說明相即為一，必須仰承佛威神。「攝受正法」這一句說明法；「攝受正法者」這一句說明人；「無異攝受正法」，說明人不異於法；「無異攝受正法者」，說明法不異於人；「攝受正法善男子善女人即是攝受正法」，上句是人，下句是法，因為人就是法，也應當以法即人，義理同前面一章。為什麼人與法能相即呢？五陰、諸入乃至一切種智，一一各有體別，這就是法；五陰諸入和合總成為人，總別不同所以有人法的差別，以別法為總人所以能相即為一。「捨三分善男子」，說明行善的人就是法，所以知道正法不是惡、不是無記。「生死後際等者」，未來生死無窮，願得聖果與它齊量，雖然有老病死，但能記知如來法身，是就極處來說：佛有聖人的名稱所以有人義，本體是善理所以有法義。另一種解釋：仰求佛果能捨三分（身命財），這是法，其餘二分也像這樣。「如是捨三善男子」，舉前面的上人；「攝受正法者，即是法也」，總結人就是法。「世尊又善男子女人者」，第五層說明護法。「朋黨諍訟者」，就是四眾弟子各隨自己的親舊，互相論是非造作各種惡業。「破壞離散者」，不讓他們諍訟，或者以善法教化，或者以威力降伏教化。「以不諂曲者」，以正直心行事，哪有什麼邪曲。「為不欺誑者」，惡就說是惡，善就說是善，怎麼會虛誑。「不幻偽者」，引譬喻說明，不像幻術虛假不真實。「愛樂正法者」，想令正法久住於世。「攝受正法者」，就是能受持護法。「入法朋中者」，就是化解諍訟的人，成為同行善知識。「之所授記者」，行善的人會被佛授記，諍訟的惡業怎麼能不捨棄呢。「亦悉知見者」，略說如來有這五種德，應當知道弟子必定能護法。"
    elif "未足之地是以求證也。大精進力起隨喜心者。" in orig and "說便縛與行不可盡也。" in orig:
        title = "【正法勝益】"
        meaning = "【義解】本段說明攝受正法有大勢力，少善就能令魔怖畏，是大福、大利、大果，利益無邊。"
        body = "白話：在未圓滿的地位，所以要求作證。「大精進力起隨喜心」，是第六層如來印可他所說的法，勤行眾善又叫精進，歡喜他能開示正法所以叫隨喜。「如大力士者」，這個比喻說明正法有大功德力。「少卑身分者」，用少許力量、卑下的人身，如同少許善力就能令魔王怖畏。「我不見餘一善法者」，如果用五戒求人天果報，用四諦、十二因緣求二乘果，不能了脫生死，魔王不怖畏；如果知道萬善都歸於佛，勤行不懈，這一一善法都能怖畏魔王。「牛王喻」是以大勝小，「山王喻」是以久勝新，也不一定取新舊之別，只要能捨三種（身命財）就勝於不捨的人。「當以攝受三正法開示眾生者」，這是如來的勸誡：勝鬘從今以後說法教化，令人修善，應當用正法。「如是大利」，是說利益他人，令一切眾生都離諸惡；「如是大福」，是具足萬善；「如是大果」，是能成佛果；「所得義利不得邊際」，是說正法的利益和修行都不可窮盡。"
    elif "汝今更說者。第五經名也。" in orig and "第一義乘解釋所以入一乘意文義區別凡有八種。" in orig:
        title = "【一乘真義】"
        meaning = "【義解】本段明第五經攝受正法就是摩訶衍（大乘），能出生一切聲聞緣覺善法，二乘戒律最終也歸於大乘，二乘並非究竟，必須歸入一乘，從八方面說明二乘應入一乘的道理。"
        body = "白話：「汝今更說者」，是第五部經的名。名義真實正法不是學地所能及，必須等佛敕令才敢說，守住本體，改變名義叫受教而說。「攝受正法者摩訶衍者」，既蒙佛命令開示，豈能不說，使所說的必定符合真理，理廣言大無所不包，一乘之義這才顯明。「摩訶衍者出生一切聲聞緣覺出世間善法者」，從這裡到「受具足故」，說明因行入大乘，先說善法從大乘出，最終還是入大乘，比如阿耨達池比如大乘，八河比如四因四果，四種人的因行善法都入大乘。「正法往者」，是佛法住世劫數長短；「正法滅者」，正法滅後到像法時期；像法滅後佛法就都滅了。「為大乘故說者」，法住法滅都是屬於大乘，為了令二乘解知沒有差別。「波羅提木叉三法也」，比丘四種法義一名異，同以遮惡為義是一，毗尼、木叉是不同名；又有一種新解釋：同是大乘名為義一，木叉、毗尼是二乘所行為異名。「即大乘學者」說明義一，善理同歸沒有大小差別。「依佛出家五法也。而受具足亦法也。何以故」，為什麼二乘的木叉、毗尼就是大乘呢？下面解釋：因為依佛出家得度，所以知道木叉就是大乘。接著又問「何故」，為什麼二乘沒有別的法可以依之出家呢？解釋：因為依佛法出家，所以知道沒有別法；如果二乘人自己有法，為什麼要依大乘佛法出家呢？「阿羅漢歸依於佛法訖去涅槃界遠」，說明果上入一乘，從前說二乘有究竟法，考察實際還需要仰求佛果，廣修行道趨向佛的究竟，所以二果歸入一乘。「有恐怖者」，從前說二乘已經斷盡所有惡，其實還有怖畏，知道惡還未盡。「何以故」，為什麼有怖畏呢？「於一切無行者」，解釋有怖畏的意思：雖然沒有分段生死的惡行，還住在怖畏的地位，知道惡未盡。「如人執劍者」，舉事比喻：天魔如同舉劍的人，生死如同劍，二乘如同自己。「無究竟樂者」，二乘還有恐怖之苦，所得的樂是少分不圓滿。「何以故」，為什麼不是究竟樂呢？「世尊依不求依」，解釋不是究竟的意思：世尊無畏，能作眾生的依靠，自己不需要找依靠；二乘有畏，要求依靠如來，不能作為他人的依靠處。「如眾生無依彼彼恐怖者」，引比喻：人不依靠君王，子不依靠父親，人天五道不依靠佛，永遠有畏懼，處處沒有歡樂。「有餘生法不盡故有生者」，說明二乘四智還不是究竟，因為不究竟所以入一乘，變易生死還存在，怎麼能說得無生智呢。「有餘梵行成故不純者」，未得如來大般涅槃叫餘梵行，二乘的涅槃惡還未盡，不能叫純淨法。解釋不是究竟無餘智。「即不究竟當有所作者」，還需要修行，不能叫盡智。「不度彼故當有所斷者」，無明住地這個煩惱還需要斷除，不能叫無作智。阿毘曇人略說二智：盡智、無生智，這部經說四智沒有差異，他們是因果合說為二，這裡是因果分開所以為四。「不成就一切功德者」解釋「有生」句，「有量功德者」解釋「不純」句，「不思議功德者」解釋「有所作」句，「有餘過者」解釋「當有所斷」句。從「言阿羅漢辟支佛」到「第一義乘」，解釋為什麼入一乘，文義分別共有八種：一說明生死未除，二說明煩惱不盡，三說明受生法不同，四說明所知未周遍，五說明所得未滿足，六說明所斷不同，七說明二智有差異，八說明三寶有差別。"
    elif "一明生死未除。" in orig and "方便引物之釋也。" in orig:
        title = "【八義入一乘】"
        meaning = "【義解】本段分別解釋八種二乘不究竟、必須入一乘的道理，說明過去說二乘涅槃是方便不了義說。"
        body = "白話：一、從「言阿羅漢辟支佛」到「故說不受後有」，說明生死未除：二乘人雖然沒有分段生死，還有法身變易生死，滅除變易生死只有一乘能做到，所以應入一乘。二、從「非盡一切煩惱」到「最為大力」，說明煩惱不盡：二乘雖然斷了三界四住煩惱，還有無明住地煩惱，要斷這個煩惱需要依靠一乘之力，所以知道應入一乘。三、從「世尊又如取緣」到「即是無明住地」，說明受生法：二乘雖然沒有四取，還有無明住地為緣，以無漏善業為因，受法身變易生死，除這個生死靠一乘之力，所以又入一乘。四、從「世尊阿羅漢辟支佛最後身菩薩」到「修有餘道」，說明所知不周遍：二乘雖然知道三界四諦法，但總的來說不知道三界之外的四真諦，要知道那個真諦一乘才能究竟，所以又入一乘。五、從「是名得少分涅槃」到「謂解脫味」，說明所得未滿足：二乘雖然經教說得無餘涅槃，實際是有餘，只得到少分；得無餘是因為行一乘，所以知道又入一乘中。六、從「世尊無明住地不斷不究竟」到「一向記」，說明所斷煩惱不同：二乘已經斷三界四住煩惱成阿羅漢果，菩薩斷除無明住地到究竟得成佛果，聲聞緣覺最終必到佛地，所以又入一乘。七、從「世尊不受後有智有二種」到「無邊不斷」，說明二智有差異：二乘的智慧只知道分段生死盡，如來能知道變易生死也盡，分段死盡不是究竟智，一切生死都盡才名究竟智，二乘人知道自己應修學一乘仰求佛智，所以又入一乘。八、從「世尊如來無有限齊時住」到「第一義」，說明三寶各別：二乘所依的三寶本體各別，又是無常；菩薩所依的三寶一體，又是常住，二乘人必須依一體常住三寶修行一乘、求常住本體，所以又入一乘。「觀察解脫者」，自己看見脫離四住煩惱、分段生死；四智究竟就是「我生已盡、梵行已立、所作已辦、不受後有」這四智，分段生死盡所以得這四個名稱。「蘇息處者」，沒有分段生死所以叫蘇息（休息）。「為餘不了義說者」，從前說二乘得無餘究竟，這是方便引導眾生的解釋。"
    elif "分段死者。三界結縛不得自由。" in orig and "一切不可得。" in orig:
        title = "【煩惱種類】"
        meaning = "【義解】本段解釋分段生死、變易生死，以及兩種煩惱：四住地煩惱與無明住地煩惱，無明住地是一切煩惱根本，難斷難知。"
        body = "白話：分段生死，就是被三界結縛不得自由，壽命長短與界地相同。「不思議者」，法身沒有繫縛，隨意住世、變化無方，淺智不能測度。「虛偽眾生者」，不知四諦、沒有無漏真智。「意生身者」，能知變化神足、念念隨意受生。「以分段死故者」，下面應有一個「無」字。「我生已盡」，沒有分段生死才受四智的名稱，義理說明完畢所以總結。煩惱有兩種：一是四住地煩惱，二是無明住地煩惱。所謂住地煩惱和起煩惱，從這以下煩惱有五個名稱：一叫四住地，二叫起煩惱，三叫恒沙煩惱，四叫上煩惱，五叫無明住地。名雖有五，本體其實有二：四住和起煩惱是一類，名不同本體一樣；無明住地是第二類。恒沙以上的名號總通二體，因為界地差別所以有四個名稱：永劫沒有斷除所以叫住，能生後續心念所以叫地，經過心識現起作用叫起，體類眾多叫恒沙，能牽引諸法叫上。不是心識現起所以叫不相應，尋求看不到所以叫無始，不認識真理叫無明，長劫以來就存在叫住，能生起不絕叫地，也因為體類眾多叫恒沙，能生起諸法叫上。無明住地，就是煩惱習氣，暗障八地到十地菩薩叫無明，法身大士只是斷而不現行叫不相應。四住地最後斷叫住，因為微細存在還能生粗煩惱所以叫地。又有一種解釋：三界四住地的結使屬於過去世的，不直接經心現起作用。又有一種解釋：眾生初始一定有神識，神識有明與不明，法有粗細，粗細的法都應該了知，因為心不明所以只了達粗法，更細的法不是心所能緣慮，這個不知就叫無明，不經心識慮知叫不相應。「最為大力」大有兩種：一是因為難斷，二是因為它是一切煩惱的根本，說它是為了讓人生厭離心。"
    elif "此三地者三乘地也。" in orig and "說便縛與行不可盡也。" in orig:
        title = "【斷惑證真】"
        meaning = "【義解】本段說明三乘地、三種意生身，八地菩薩斷部分無明，佛地完全斷盡；無明住地斷後才能得究竟解脫，成就法王、法主、得大自在。"
        body = "白話：這三地是三乘的地。彼三種意生身，未來無量的叫彼，過去已經有的叫此，不同的差別說明受生之前的狀況。「八地所斷者」，為什麼說斷呢？說明佛已經斷盡，受生的三種人（三乘）還未斷除所以有生死。「畫然無處」是佛地得名。「無漏不盡者」，三乘人雖然能斷結使，無漏還未窮盡，下面會說明，就是無明住地。「於彼彼法者」，是無邊的聖諦，還在他們的本分之外，也不是只有一種。「所應斷者者」，就是無明住地。「名有餘過解脫者」，沒有分段生死的地方還未能永除煩惱。「有餘清淨者」，雖然斷了四住，但無明住地煩惱還在。「成就有餘功德者」，雖然得十智，但種智等功德還未得到。「知有餘苦乃至有餘道者」，先說明所得三事有餘，接著說所知不周遍。「是名得少涅槃者」，滅除四住分段生死得名涅槃，本體還未滿足名叫少分。「知一切苦者」，是粗法的苦，集、滅、道三諦也是這樣，所以能了知的，智慧周遍，所得涅槃必定是滿足的。"
    elif "無常壞世間者。生死果報也。" in orig and "非真歸佛也。" in orig:
        title = "【如來常住】"
        meaning = "【義解】本段明如來法身常住，是究竟歸依處，過去說應化身佛入涅槃是不了義說，二乘所歸的是應化身，不是真實歸依法身佛。"
        body = "白話：「無常壞世間」是生死果報；「無常病世間」是生死因；「得常住涅槃者」，得佛滿足究竟涅槃。「於無覆護世間者」，不能免四魔；「無依世間」，生死中的人不可依靠。「何以故」，為什麼如來能護、能作依靠呢。「法無優劣者」，十力、無畏同等沒有高下；「智慧等者」，種智、無生智、自然智沒有差別；「清淨等者」，同無煩惱；「解脫等者」同無生死；「三昧等昧者」都是滿足之地，沒有勝過佛的；「謂解脫味者」，沒有煩惱的境地齊等所以說等。「若無明住地不斷不究竟者」，將要說明斷無明的利益，先說不斷的過失：「不得一味者」，不得佛的解脫味，這是第一過；「應斷不斷者」，無明諸惑未能滅除，這是第二過；「應得不得者」，不能得萬善，這是第三過；「應證不證者」，不能證成佛的法身，這是第四過。所以無明住地積聚，總集上面諸多過失，又說明無明本體有眾多過患。「生一切修道者」，修諸無漏法，是能斷的智慧；「斷煩惱上煩惱者」，這是所斷的煩惱，上煩惱就是障蔽神識令不明淨的。「止是四依」，安立止觀的智慧；「禪是四禪諸定」；「正受是四正受」；「方便是涉求的智慧」；「智是實智」；「果是人天三果」；「道果得是人天三乘之因，有煩惱果的力量所以給他名字」；「力是十力」；「無畏是四無畏」。「一切皆是無明住地之所建立者」，這是說明煩惱相生的由來，這部經大意，以無明住地是一切結使的源頭，凡生起煩惱都是先細後粗，斷結的道路是先斷粗後斷細，根據這兩義知道無明住地生四住地。「無明住地自相生者」，金剛喻定所斷的是細，下至八地所斷的是粗，所以一點點有生起都是因為它。「一切上煩惱起皆因無明住地緣無明住地者」，上煩惱通於四住和無明住地，對於四住地來說疏遠所以是緣，對於無明住地來說親近所以是因。「心不相應無始無明地者」，要說明斷除所以稱它的名字；「所持所建立者」，說明它的過患。一切煩惱（四住、恒沙、起煩惱）都和無明相應，上煩惱總說兩類，斷除後五種（過惡）都滅。「所得諸法通達無閡者」，善於理解一切諸法的道理；「離一切過惡者」，沒有煩惱生死；「得一切功德者」，萬善完備；「法王法主者」，無明住地斷滅後就能具備這三種意義，具足三義就成佛，統攝諸法為王，超勝萬物為主。「而得自在者」，獨特圓滿超勝，不被萬物屈折。從「我生已盡」到「不受後有」，說明如來具足四義，無餘究竟至極圓滿，不像二乘有餘不足。所以從「是故世尊」到「一向記說」，總結上面所說佛是究竟、二乘未滿足，符合真理沒有虛妄，決定真實的說法才能稱得上無畏之言。「不受後有智有二種者」，說明兩種果，如來的智慧都得名為不受後有。「謂如來以無上調御者」，下面說師子吼，說明如來的智慧，十號中略說二號（無上調御、天人師）。「降伏心過四魔者」，除惡淨盡；「得如來法身者」，所得圓滿；「一切爾炎者」是境界，說明所知諸法因緣完備；「於上更無所作者」，在佛地已經不需要再修萬善；「無所得地者」，至足究竟沒有再可求的；「無閡智觀者」是一切種智；「不由於他者」，一切法都知，不需要諮詢他人；「度生死畏者」，說明二乘人的不受後有智，除分段生死所以叫度；「不更受生者」，叫不受後有；「次第得解脫樂者」，分段除後接著得有餘涅槃；又一解是二乘的微樂和如來的大樂形成次第；「得不受後有觀者」是智人的異名；「第一蘇息者」，剛剛免難，出離分段生死，是第一個少樂，還未得到常住大樂；又一解是二乘自認為是第一殊勝法。「處涅槃地者」，說的是蘇息處地；「彼先所得地者」，如來最初說四諦時教二乘斷三界四住結盡，捨最後身得無餘涅槃，從前認為這是真實，叫先所得地；等到說明還有念念變易生死，自己就覺知這是有餘地，應當得無上菩提。"
    elif "何以故者。勝鬘釋其應解之意。" in orig and "非究竟歸依者。" in orig:
        title = "【究竟三歸】"
        meaning = "【義解】本段明究竟歸依：法身佛是真歸依，一乘正法是法歸依，一乘聖眾是僧歸依，過去說的三歸是不了義、少分歸依。"
        body = "白話：「何以故」，勝鬘解釋應當理解的意思：三乘既然歸於一，窮盡自己所行之道，哪有不知道的。「即是佛乘者」，說明以自己的智慧得佛的意思。「即是涅槃界者」，道尊超勝叫菩提，眾累盡除叫涅槃，能應眾求叫種（種性）、叫做法身，三義雖異本體是一，就是究竟一乘，得佛法身乘的功用就止息了，所以知道二乘不是終極。「無異如來無異法身者」，說明如來法身是一。「得究竟法身者究竟一乘者」，舉兩句來說明無邊不斷：佛體常住應現十方叫無邊，沒有念念生滅叫不斷。「如來無有限齊時住後際等住者」，這兩句說明法體常住；「無限大悲無限安慰世間者」，這兩句說明教化無窮。「是名善說如來者」，說如來化度無窮才是得其實，叫善說；如果說如來在雙樹林入滅，就失去佛的真實，不能叫善說。「無盡法常住法者」，說如來法身是常住，才是得其實，叫善說；如果說如來壽盡在雙樹，只是丈六應化身，就不叫善說。「一切世間之所依者」，法身常住真實能作依靠，依這個才最真實。二乘從前歸依丈六應化佛以為真實，現在說法身常住的佛是大士所歸，所以知道二乘還未歸依真佛。「是故未度世間者」，生死未除；「無依世間」，善未滿足所以沒有真實依靠。「與後際等作無盡歸依者」，如來法身盡未來際常住，常給眾生作歸依；「處常住歸依處常住歸依者，謂如來等正覺者」，就是法身佛，說出真實歸依的本體，常住佛寶說到這裡。「法者即是說一乘道僧者是三乘眾者」，這裡說明過去所說的法、僧不真實：萬善是法寶，三乘人是僧寶，這是二乘從前所依的；「非究竟歸依者」，不是究竟歸依常住一體的法、僧，叫少分，雖然無常但因為是聖人所以可暫時依靠。"
    elif "何以故者。何以少分者也。說一乘道法得究竟法者。" in orig and "非此二歸依是歸依如來者。" in orig:
        title = "【一體三寶】"
        meaning = "【義解】本段說明究竟歸依就是歸依第一義（法身如來），歸依法身就同時歸依法、僧，因為三寶一體不二，過去所說的分相三寶是方便說。"
        body = "白話：「何以故」，為什麼是少分呢？「說一乘道法得究竟法者」，解釋法是少分，因為它是得究竟法的因，所以知道是少分；「於上更無說一乘道法得究竟法事者」，在佛果地上更沒有可求的。「三乘眾者有恐怖者」，解釋僧是少分，因為生死未除、煩惱未盡，求出離諸惡、修行萬善向無上道所以叫少分。所以這兩種歸依的對象是有限的，總結法、僧是少分。可盡的法、可捨的聖人叫有限。「若有眾生如來調伏」，說明過去為二乘人說三歸，是如來初現化身，調伏邪見眾生令信三寶。「歸依如來者」就是丈六佛；「得法津澤者」就是受行佛教；「生信樂心者」，相信有善法和聖人；「歸依僧者」就是受持另外二歸：一乘為法，三乘聖人為僧，這三歸依是權說的法、僧。舉這二歸來說明歸佛，「非此二歸依是歸依如來者」，上面說「非」，是想說明過去歸依法、僧的人，只歸依丈六化身，不知道歸依法身如來。"
    elif "歸依第一義者是歸依如來者。法身常住名第一義天也。" in orig and "菩薩知明為說法身體一三寶也。" in orig:
        title = "【三歸一體】"
        meaning = "【義解】本段明第一義（法身）才是真歸依處，歸依第一義就同時歸依三寶，因為佛地圓滿三寶一體，對鈍根人說分相三寶，對利根菩薩說一體三寶。"
        body = "白話：「歸依第一義者是歸依如來者」，法身常住叫第一義天，如果知道歸這個才是真歸佛。「此二歸依第一義是究竟歸依如來者」，這歸依法、僧的人，知道歸依法身就是歸依一體的佛法僧。「何以故」，因為歸佛就自然得到法、僧。「無異二歸依者」，本體既然沒有差別，歸一就得到另外二個。「如來即三歸依者」，大覺名佛，可軌範名法，體常住和合順名僧，佛地圓滿所以具備這三義；學地未圓滿所以別立名稱。二乘智慧暗昧，為他們說粗顯的別體三歸；菩薩智慧明了，為他們說法身一體三寶。"
    elif "何以故者。何以體一而有三名也。說一乘道法者。" in orig and "更無異趣也。" in orig:
        title = "【一乘方便】"
        meaning = "【義解】本段解釋為什麼一體說三名，是如來以四無畏，隨眾生根機方便說三，究竟唯一大乘，沒有二乘。"
        body = "白話：「何以故」，為什麼本體一而有三個名呢？「說一乘道法者」，解釋為什麼分三的意思：乘體是一，隨人的根機說三。引這個有兩個意思：一是用來證明義理，二是用來歸結宗旨。「如來四無畏者」，這裡說明如來通達無礙，所以能隨人根機在一乘法上說三乘。「若如來隨彼所欲而方便說者」，說明如來不妄說法，人的喜好不同所以方便說三。「即是大乘者」，乘名雖然三個，本體其實是一個大乘法；「無有二乘者」，沒有二乘的別法；「入於一乘者」，既然沒有別法，怎麼會不入呢？這一章所說無歸，此文說一乘，就是第一義乘，只有法身，沒有其他歸趣。"
    elif "聲聞緣覺初觀聖諦者。第六經名也。" in orig and "二義以訖。是以結之。" in orig:
        title = "【聖諦漸頓】"
        meaning = "【義解】本段明第六經義：二乘初觀四聖諦是漸次智，佛智是圓滿頓照，唯有如來得究竟第一義智，能斷一切煩惱、照了一切法。"
        body = "白話：聲聞緣覺初觀聖諦，是第六部經的名，是聖諦的開始。將要說明聖諦有粗細，先辨明智慧有明昧，諦既然有粗細，修學也有漸次，初觀粗諦就叫初。「以一智斷諸住地者」，一切斷結的智慧同一個無礙智，所以叫一智；又一解是觀一個滅諦來斷結的智慧。「以一智四斷知功德作證者」，一切證結盡的智慧同一個解脫名；又一解是觀一個滅諦證得結盡的智慧，也能善了知。「此四法義者」，分明了了見四真諦；又一解是要觀滅諦須先觀四諦。「無有出世間上上智四智漸至及四緣漸至者」，說明佛智圓滿沒有漸次增進，世間有兩種：一分段身、二變易法身，如來已經遠離叫出世，大士在二乘凡夫之上，如來又超勝所以叫上上。捨苦觀集、乃至捨滅觀道，境智不同時所以叫漸；如來一智圓照諸法，不叫漸至法，是出世間上上智。前面說不是漸，這裡說明圓照。「金剛喻者是第一義智者」，這裡說明斷結不同：二乘的種智只是大解脫，不能滅一切惑；從「非聲聞緣覺」到「第一義智」，說明二乘不斷無明住地煩惱，初觀三界粗的四聖諦，得不到第一種智的名稱。「以無二聖諦智斷諸住地者」，這是說明佛智，只觀無作諦，不再考慮有作，所以說無二；四住、無明一切都盡名叫諸住地。「非聲聞緣覺境界者」，佛地幽微不是二乘所能及。「不思議空智者」，法身難測叫不思議，眾患都除叫空智；「是究竟智者」，煩惱盡智慧周，寂然無事，二義都完畢，所以總結。"
    elif "初聖諦智者。二乘之人見理不周" in orig and "非思量境界者。" in orig:
        title = "【二種四諦】"
        meaning = "【義解】本段明有兩種四諦：有量四諦（有作四諦，是二乘所觀）和無量四諦（無作四諦，是佛所觀），無作諦微細難知，唯佛與菩薩能了。"
        body = "白話：「初聖諦智」，二乘人見理不周全、除患未盡，還需要尋求向無上道，總結二乘的智慧。「聖義者訖名之為聖」，說明二乘的聖名還不真實，功德薄少所以說有量、少分。「聖諦者非聲聞緣覺諦者」，已經說明聖名不真，現在又說明知諦未盡，無作、無邊的聖諦二乘不能了解。「非聲聞功德者」，盡道是善、能生善。「初始覺知者」，剛成佛時才能知道窮盡。「開示演說者為未知者說使解也。」「說甚深義微細難知者」，有為諸法事相眾多，隨類粗細大約有二種：一是粗顯，二是微細。三界結縛叫粗，這裡的法受切叫粗：苦能逼迫叫苦（苦諦），能生起苦叫集（集諦），斷處叫滅（滅諦），觀知叫道（道諦），為二乘人說這四諦。不繫在三界的八地以上法身菩薩到金剛心所觀的諸法叫細，這裡的法受切叫細：苦能逼迫叫苦，能生起叫集，斷處叫滅，觀智叫道，佛地無為也歸入滅諦，理深義遠，當然大士才能得知，不是因為空無才叫微細。「非思量境界者」，不是用二乘可思議的智作境界。"
    elif "是智者所知者除四住結智惠憎明乃能解也。" in orig and "必能知諦有二種也。" in orig:
        title = "【如來藏義】"
        meaning = "【義解】本段明如來藏（佛性），分兩種：眾生佛性（在纏如來藏）和如來佛性（出纏法身），能信解二種佛性就能了知二種聖諦。"
        body = "白話：「是智者所知者」，除了四住結使、智慧明朗的人才能了解。「一切世間所不能信者，轉迴六趣者」，輪轉六道的眾生不能知道有無作諦。「此說如來甚深之藏者」，是佛性的異名，體不改變叫性，完備含攝眾德叫藏，屬於滅諦所攝，所以用這個解釋。「如來藏者是如來境界者」，是第七部經的名，只有佛能明了。「若於無量煩惱者」，是第八部經的開始，眾多煩惱積聚為藏；「所纏如來藏者」，就是眾生的佛性。「法身亦無疑惑者」，能信如來佛性，也能信煩惱纏縛的眾生有大智慧本性，必能信知無惑的解脫就是有大智慧。「於說如來藏訖及方便者」，對於二種佛性沒有疑惑的人，必定能方便為人解說。「此則信解說二聖者」，解了有二種佛性，就能解二種聖諦，知作諦名叫眾生佛性，解無作諦得如來佛性，既然知道性有二種，必能知諦有二種。"
    elif "如是難知難解者。此下解釋二種諦義也。" in orig and "常住者湛然也。自性清淨者無諸惡也。" in orig:
        title = "【苦滅常住】"
        meaning = "【義解】本段解釋二種四諦（有量有作、無量無作），闡明苦滅諦是常住、不生不滅、自性清淨，是如來法身，不是無常破壞的滅。"
        body = "白話：「如是難知難解者」，下面解釋二種諦的含義：「作聖諦義、無作聖諦義者」，可以修學證得的叫有作，不需要再修學的叫無作，是有教、無教的不同名稱。「是說有量四聖諦者」，三界因果各有定期叫有量。「非因他能知一切苦說一切道」，有一種解釋認為：靠教導得知三界少分四諦，不是靠自己智慧之力了知一切無作四諦。「有有為生死者、無為生死者」，諦既然有有為無為，生死也是一樣：凡夫輪轉不斷煩惱叫有為生死；二乘已經斷三界四住叫無為生死。「涅槃亦二種：有餘及無餘者」，分段生身叫有餘。「能以自力知一切受苦訖受滅道得法身者」，智慧轉明、自悟的力量多、師承的意味少，究竟明見四諦理盡。「如來說四聖諦者」，名字相同理趣順同，因為守持四隨、法有粗細，所以有八種（二種四諦）。「如來應等正覺事究竟者」，無作之理唯佛能窮盡，不是二乘所能究竟。「何以故」，為什麼二乘在無作諦上不能得究竟呢？「非下中上法得涅槃者」，解釋原因：二乘如果得無作究竟，所得涅槃應和佛相同，無餘涅槃沒有下中上的差別；如果以聲聞為下、緣覺為中、佛為上，就知道二乘不能同佛一樣觀無作諦。「何以如來說事究竟」，這裡說明如來為什麼能在無作諦上得究竟：「以一切如來者」就是諸佛，「知一切未來苦者」就是知一切法，未來難知，過去現在容易理解，所以不別說。「一切煩惱所攝受一切集者」，四住、恒沙、起煩惱和無明，都是一切集諦法。「一切盡是集諦法也。滅一切意生身陰。一切苦滅作證者」，意生身盡、分段生死也除，在後面滅，所以就此立言。「非壞法故名為共滅者」，不是分段、意生、變易這些無常破壞、念念生滅的法滅，所說的苦滅是常住的滅：「無始者」不從生開始，「無作者」非因緣造作，「無起者」沒有動搖生起，「無盡者」沒有終結滅壞，「離盡者」沒有滅盡之相，「常住者」湛然不變，「自性清淨者」遠離一切惡。"
    elif "離一切煩惱藏者略說一患也。" in orig and "未得佛性用在已也。" in orig:
        title = "【二種如來藏】"
        meaning = "【義解】本段明二種如來藏：空如來藏（如來果位，離一切煩惱）和不空如來藏（眾生佛性，具備不思議佛法），二乘人空觀只證人空，未見佛性。"
        body = "白話：「離一切煩惱藏」是略說一種過患。「過於恒沙不離者」，這是說明佛性，還沒有了脫生死；「不脫者」沒有脫離煩惱；「不異者」還沒有和世間超然區別。「不思議佛法者是佛性也。」明佛性說完，接著說「如來法身」：行滿惡除、種智起現用，這是說法身。「不離煩惱藏明如來藏者」，這是說明眾生位的佛性（在纏如來藏），眾生佛性還沒有脫離煩惱，為什麼在法身文中說眾生佛性呢？為了說明眾生佛性和如來佛性本體相同沒有差別，所以說眾生當來有如來的功德，因為已經有種子。「如來藏智者如來佛性也」，如來的空智就是無生、無煩惱、離一切相累，只舉前面一句來說明這個意思。「如來藏者」，再舉這一句，是想說明三乘行人還沒有見到、沒有證得。"
    elif "有二種者第九經名也。" in orig and "道諦滿足者無過佛地。" in orig:
        title = "【空與不空】"
        meaning = "【義解】本段明第九經二種如來藏：空如來藏（離一切煩惱）和不空如來藏（具不思議佛法），說明二乘和凡夫都不能通達，只有佛能究竟證得。"
        body = "白話：「有二種者」是第九部經的名：如來藏是眾生佛性，是一種；空智是如來佛性，是第二種。「空如來藏者，若離說一切煩惱藏」，這個解釋空智（如來佛性）；「不空如來訖不思議佛性法」，這個說明眾生佛性。「此二者」就是上面二種佛性、空智，「諸大聲聞者」，沒有四住分段煩惱就是空智（二乘的空是偏空）；「菩薩有大心聞一乘也」，能信受如來所說；「能信如來者」，大士有智慧能信佛說的二種佛性。「一切阿羅漢說境界轉二乘之人」，二乘人雖然沒有四住分段生死，但對於四種無作諦還不能照了，對於二種佛性也不能了解。「本所不見者」，二乘差很遠，能解無作諦、二種佛性的是菩薩。「本所不得者」，無作諦沒有在心中修行，佛性的作用沒有在自身實現。「一切苦滅唯佛得證者」，所有苦都滅除，只有佛能做到，湛然常存才可以叫真滅諦。「修一切苦道者」，這是總結道諦，要斷盡煩惱必須具足智慧，道諦圓滿的只有佛地。"
    elif "三是無常一是常者。第十經名也。" in orig and "非正見者實非寂滅故言非也。" in orig:
        title = "【四倒與正見】"
        meaning = "【義解】本段明第十、十一經：苦集道三諦無常，唯滅諦常住；凡夫有斷常二見和四種顛倒，二乘也未見真實滅諦，唯有菩薩信佛語能得正見。"
        body = "白話：「三是無常一是常者」，是第十部經的名，「非第一義諦者」，因為常住的才是第一義，其他三諦無常所以說非第一義。「一苦滅諦離有為相者」，是第十一部經的名，超過一切眾生心識所緣，凡夫沒有智慧，怎麼能知道呢？也不是阿羅漢、辟支佛的智慧境界，二乘智慧淺薄不能了解。「譬如生盲者」，用凡夫作比喻，沒有無漏的觀滅智慧，看不見青黃赤白等種種色，就像看不見滅諦一樣；「七日嬰兒者」，比喻二乘，得到無漏智就像嬰兒眼睛剛睜開，看不見日輪，雖然知道有作的滅諦，還不能通達無作滅諦，就像嬰兒看不見太陽一樣。「凡夫識者二見顛倒者」，這是說明凡夫如生盲：一是計斷、計常二種邊見，二是四種顛倒，就是不清淨的見解。「邊見者」解釋二見：計斷、計常就偏離中道。「於五受陰者」，列出產生見解的地方；「我見者」把五陰當成我；「妄相計著實非真我妄計為實」。「生二見者」，在這個我上面生起兩種見解，就叫邊見，所謂常見、斷見。「見諸行無常者」解釋斷見：見五陰一期生死結束就認為永遠滅了，不是正見，因為不是真實寂滅所以說非。「見涅槃常者」：見五陰暫時存在就認為是常存，當作涅槃，也不是正見，無常說成常所以說非。"
    elif "妄相見故者。皆是虛妄非真見也。" in orig and "名當得也。" in orig:
        title = "【凡小之非】"
        meaning = "【義解】本段進一步解釋斷常二見的生起，說明二乘雖斷四住仍未見真諦，三乘初業最終都能覺悟證得。"
        body = "白話：「妄相見故者」，都是虛妄不是真實的見解。「於身諸根者」就是五陰六情；「分別思惟者」，知道這是五陰六情；「現在佛見壞也」，在現實五陰上見死壞；「於有相續者」就是此死彼生，看不見死後生到何處，或者生到他方、或者得聖道，因為看不見這個就說永滅，生起斷見就是因為這個。「於心相續者」，要說明常見先說明心體是無常，人天六道中念念心識相續，此滅彼生念念不停，愚闇不解的無明凡夫不知道相續，不知道剎那間的意識境界，不知道心是念念生滅，就生起常見，不知道念念生滅就認為是常。「若過若不及者」，心實際是無常就說是常，是超過了心的實相；心滅了會更生看不見後續，就說一心常存不變，是不及。五陰還未盡就認為已經盡了，是超過陰的實相；滅了更生而看不見，是不及。又一解：心是無常認為是常叫過，五陰相續不知道更生叫不及。又一解：五陰相續就認為永滅，是違背相續的道理；心體念念此滅彼生不知道後念，就認為是一常，叫不及。又一解：計斷、計常，都是過和不及的事。「顛倒者」，稱名來解釋，經文少了「眾生」二字，眾生於五受陰無常常想、苦有樂想、無我有我想、不淨淨想，就是四種顛倒。「一切阿羅漢者」，解釋二乘人見滅諦不圓滿：在一切境界中，無作滅諦以種智為境界；以及如來法身，法身無為歸入滅諦。「本所不見者」，二乘從前開始修學觀有作滅諦，還不能觀無作滅諦。「或有眾生信佛語故說淨波羅蜜」，說明菩薩能信解知無作滅，「是名正見者」，法身之體是常樂我淨，這樣理解才是真正的正見；「真子者」，見正理而成為聖弟子中的真實佛子；「得法餘財者」，在無常的三乘言教中，得以聽聞常住大乘，可見這部經一定在《法華經》《涅槃經》之前。「世尊淨智者」，這裡說明二乘將來必能解知無作滅諦，斷了四住煩惱才能名為淨；「尚非境界者」，二乘剛斷三界四住時還有結業、後邊身存在，那時還不能觀無作諦，何況四依的智慧呢？觀四作諦是生死智，以上況下。「何以故」，為什麼作諦智不能知無作諦呢？「三乘初業不愚於彼義當覺當得者」，解釋為什麼現在不知：捨最後邊身得變易法身，就知道生死未盡、觀諦不周全，更應觀諦、修諸善行向佛涅槃。如來方便引導到這個地方令他生解，從前不知現在才解悟，所以叫初解，自在心叫不愚；還沒有圓滿解悟所以說當覺，將來必定成就無為法身名叫當得。"
    elif "為彼故世尊說四依者。" in orig and "所謂滅諦者列名也。" in orig:
        title = "【四依歸一】"
        meaning = "【義解】本段明為了引導二乘說四依（四諦），實際上世間法都依止第一義（常住滅諦），第一義才是究竟依止處。"
        body = "白話：「為彼故世尊說四依者」，為了二乘人了解無作諦，所以先為他們說有作的四諦。「此四依者是世間法者」，還要歸結成常住的一依，四諦是有為法，不免三世流轉。「此句總漫未有所執甄一依也。一切依上者」，回到前面的句子點出滅諦：苦、集、道諦是「一切」，滅諦是「一依」。「無作無為勝三言上也。一切依上者」，直舉前句，「出世間上上者」，有作的滅聖諦在凡夫之上，無作諦更殊勝，叫上上。「第一義依者，常住湛然，所謂滅諦者」，列出名稱。"
    elif "生死者依如來藏者。第十二經名也。" in orig and "非其境界者。" in orig:
        title = "【生死依藏】"
        meaning = "【義解】本段明第十二經：生死有為法依如來藏（佛性）而有，如來藏本身常住不生滅，是眾生厭苦求涅槃的根本，但凡夫、二乘都不能如實了知。"
        body = "白話：「生死者依如來藏者」，是第十二部經的名，有為生滅的生死，依於無為常存的如來藏，這是說明眾生都有二種法藏。因為生死將要除滅，不會長久存在，所以說依於如來藏。「以如來藏故說本際不可知者」，不是初始造作、最終成就，能知道開端；「有如來藏故說本生死是名善說者」，如果說眾生有藏（佛性）而有生死，這個說法是善說。「生死生死者」，前列後稱。「諸受根者」，解釋生就是死，五陰六情一時壞滅；「次第不受根起者」，死後還沒有再受生叫生死。解釋生和死完畢所以總結，「生死者」想說明死後還要受生，所以先列。「此二法是如來藏者」，凡夫眾生有生有死叫顛倒，這章開始說諸眾生都有二法，意思就在這裡。「世間言說故有死有生者」，說如來藏是生死，這是世間愚人的說法，不是聖語。又有一義：世間諸法可說有生有滅，如來藏是出世無為法，沒有生死。「死者諸根壞生者新諸根者」，還是說明死者再轉變為後世的生，生而死、死而生，三世無常的事相顯現。「非如來藏有生有死者」，藏體湛然，沒有六情諸根，真實常住不是生死法。「離有相常住不變者」，藏體這樣所以沒有生死。「是依是時是建立者」，超然於形相之外的就是如來藏，如來能讓眾生作歸依處，堅持獨立不被萬物壞亂。「不離不斷訖不思議佛法」，說明眾生佛性；「斷脫異外訖是如來藏」，說明如來佛性：斷煩惱叫斷，解脫生死叫脫，超出三界叫異，不是念念生滅叫非有為，以上四絕叫外，「外」字應該在後面。有為法下面一段講藏體真實，到這裡結束。「若無如來藏者不得厭苦樂求涅槃者」，這裡說明佛性有益於人，佛性本體常樂我淨，生死之法苦惱眾多，受久了就生厭患心，尋求快樂之法來安頓自己，因為有佛性才能生起這個心。「何以故」，為什麼有眾多苦呢？「於此六識及心法智者」，解釋為什麼多苦：心是主，所以叫心法智；「剎那不住者」，念念生滅不停，苦就很多。「不種眾苦不得厭苦樂求涅槃者」，苦到極頭自然會尋求出離，理數必然，這說明佛性能生厭苦心。「如來藏者，無前際不起不滅法也，非三世攝。前際為未來不起為現在滅為過去。體是常存令人樂求。世尊如來藏者非我非眾生非命非人者」，說明佛性常寂真實，不像外道所計的我、人、眾生、壽命那樣是虛妄的常。「如來藏者墮身見眾生者」，就是執斷常的人，把五陰當我又叫身見。「顛倒眾生者」就是有四倒的人；「空亂意眾生」就是二乘人，證得人空沒有四住分段，就以為是小乘涅槃，是散亂的空見。「非其境界者」，上面三種人惑累未除，不以佛性為境界。"
    elif "是法界藏者。是第十三章經名也。" in orig and "不退轉者，則能具修萬善向佛也。" in orig:
        title = "【自性清淨】"
        meaning = "【義解】本段明第十三經法界藏，自性清淨心雖為客塵煩惱所染，但本性清淨，唯有佛能如實知見；信佛語者得三種忍，能入大乘不退轉。"
        body = "白話：「是法界藏者」，是第十三章經的名，「十方不共慈悲等也。法身藏者佛性身也。出世間上上藏者，無為常住也。自性清淨藏者，體非惑累也。而客塵煩惱上煩惱所染者」，煩惱可以斷盡所以叫客，障蔽心不明叫染。「剎那善心非煩惱所染者」，煩惱以闇惑為體，心以慮知為體，雖然說同處但永遠不順從。又有一解：善心初生和住煩惱不同時，怎麼能互相染呢？然而有煩惱的時候就有煩惱染心，雖然不同時但不能免離，假名之道所以說有染。「自性清淨心而有染者」，事理上就是這樣，通達道理就可以知道，眾生雖然有清淨佛性，還未脫離煩惱就叫染。「難可了知者」，清淨不應被染、染就不應清淨，說清淨又說有染，言辭隱含玄理，不是學地所能理解。「如實知見者」，佛具足五眼、一切種智，是眾善所歸，通達了解諸法才能知道。「問於佛時」，向佛諮問決定，所以叫問。「如是如是者」，之前諮問現在印可，說明沒有錯謬。「唯信佛語者」，大士利根得道後修行，二乘根機差，信而不解。「隨信信增上者」是上品信忍；「隨順法智者」是順忍人；「而得究竟者」，具足上面二忍，信有佛性就不會退轉。「觀察諸法施六根也。若知學地有此觀智，當知佛地必有佛性大明智也。觀察業報者，若知學地有因有果，亦能解知有佛性果萬善因也。觀察阿羅漢眼者，小乘經說羅漢無眼（不見佛性），現在見有眼（有佛性種子），知非究竟必有佛性常覺不眠。觀察心自在樂者，得自在的心就受快樂，三禪之中也有樂根，所以知道必有佛性之樂。觀察聖自在通者，如果三乘聖人學地常有自在神通，所以知道佛地必有佛性的大神通。是究竟者入大乘道。染信佛性不退轉者，就能具足修萬善向佛。"
    elif "因信如來者。得如是大利益不謗染義者。" in orig and "第十五經無別文。自總上所說以為多也。" in orig:
        title = "【流通分】"
        meaning = "【義解】本段明第十四經：佛滅後流通此經能降伏惡人、令法久住，得大利益；最後是寫經題記。"
        body = "白話：「因信如來者，得如是大利益不謗染義者」，因為信佛語知道有佛性，又能理解大乘之道，不會毀謗說染淨之義不對。「更有餘大利益者」，是第十四部經的名：佛去世後降伏惡人，令法平等流布，一切人信受奉行。「離自毀傷者」，不毀謗大乘；「生大功德者」，生大乘法的功德；「自成就甚深法智者」是無生忍人；「隨順法智者」是順忍人；「仰惟世尊唯佛所知者」是信忍人。這三種忍的人聽聞佛性大乘就能受持奉行。「諸餘眾生者」，下面說非法器的人：「堅著妄說者」，說三乘因果各別；「違背正法者」，不隨順一乘；「習諸外道者」，修學外道經書論議；「腐敗種子者」，沒有能力成就佛法身，就像燒焦的種子不能發芽。「王力天龍鬼神力者」，這些力量能藉國王護法、天神摧伏惡人。「頂禮佛足者」，諸佛印可。第十五經沒有單獨的經文，是總結上面所說的法義，內容豐富。「過眼境界者」，不是眼目能看到的地方；「具足念佛者」，念佛的十力、無畏、相好光明等內外一切功德。慧掌蘊。正始元年二月十四日書寫完畢，用紙十一張。《勝鬘師子吼一乘大方便方廣經》，寶獻和玄濟上人共同校勘完畢。"
    else:
        title = "【本段大意】"
        meaning = "【義解】本段為經記內容，直譯如下。"
        body = f"白話：{orig}"
    
    seg['modern'] = f"{title}\n{meaning}\n{body}"

